CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('ADMIN','CUSTODIAN','EMPLOYEE')),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX users_email_unique_ci ON users(LOWER(email));
CREATE TABLE sessions(id UUID PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE assets(id BIGSERIAL PRIMARY KEY,asset_tag VARCHAR(40) NOT NULL,name VARCHAR(160) NOT NULL,category VARCHAR(100) NOT NULL,serial_number VARCHAR(120) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','ASSIGNED','MAINTENANCE','RETIRED')),purchase_date DATE,purchase_cost NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(purchase_cost>=0),assigned_to BIGINT REFERENCES users(id),created_by BIGINT NOT NULL REFERENCES users(id),updated_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((status='ASSIGNED' AND assigned_to IS NOT NULL) OR (status<>'ASSIGNED' AND assigned_to IS NULL)));
CREATE UNIQUE INDEX assets_tag_unique_ci ON assets(LOWER(asset_tag));CREATE UNIQUE INDEX assets_serial_unique_ci ON assets(LOWER(serial_number)) WHERE serial_number<>'';CREATE INDEX assets_status_idx ON assets(status);CREATE INDEX assets_assigned_to_idx ON assets(assigned_to);
CREATE TABLE asset_events(id BIGSERIAL PRIMARY KEY,asset_id BIGINT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,type VARCHAR(20) NOT NULL CHECK(type IN('ASSIGNED','RETURNED','MAINTENANCE','RETIRED','AVAILABLE')),from_user_id BIGINT REFERENCES users(id),to_user_id BIGINT REFERENCES users(id),notes VARCHAR(1000) NOT NULL DEFAULT '',performed_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX asset_events_asset_idx ON asset_events(asset_id,created_at DESC);
